values ('bd586991-0496-4a4e-8e25-3968b0075d61', '613f7d07-a170-4ad5-8c5a-f303513aea00', 'പുട്ട്', 'Puttu', 'ആവിയിൽ വേവിച്ച അരിപ്പുട്ട്. കടലക്കറിയോ പഴമോ കൂടെ.', 'ml',
